from __future__ import annotations

def repeated_127(n: int) -> int:
    """Compute the nth repeated-127 term by affine recurrence."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    value = 127
    for _ in range(n):
        value = 1000 * value + 127
    return value

if __name__ == "__main__":
    for i in range(8):
        print(i, repeated_127(i))

from __future__ import annotations

def repeated_127_closed(n: int) -> int:
    """Compute the nth term from its exact geometric-series formula."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    numerator = 127 * (pow(1000, n + 1) - 1)
    value, remainder = divmod(numerator, 999)
    if remainder:
        raise ArithmeticError("expected exact division")
    return value

if __name__ == "__main__":
    for i in (0, 1, 2, 10, 50):
        value = repeated_127_closed(i)
        print(i, len(str(value)), str(value)[:24] + ("..." if len(str(value)) > 24 else ""))

from __future__ import annotations
from fractions import Fraction

def audit(n: int) -> dict[str, bool]:
    """Check the closed form, suffix, bounds, and normalized error."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    f = int("127" * (n + 1))
    p = 1000 ** (n + 1)
    return {
        "closed_form": 999 * f == 127 * (p - 1),
        "suffix": f % 1000 == 127,
        "lower_bound": 126 * p < 999 * f,
        "upper_bound": 999 * f < 127 * p,
        "exact_error": Fraction(127, 999) - Fraction(f, p) == Fraction(127, 999 * p),
    }

if __name__ == "__main__":
    for i in range(6):
        print(i, audit(i))

